1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>orchestrator monitor</title>
7	<style>
8	  :root {
9	    --bg: #0f1117; --panel: #171a23; --panel2: #1d2130; --text: #e6e8ee;
10	    --muted: #8b90a0; --line: #2a2f40;
11	    --queued: #8b90a0; --running: #e8b23c; --done: #4cc38a; --failed: #e5534b; --info: #6ea8fe;
12	  }
13	  @media (prefers-color-scheme: light) {
14	    :root { --bg:#f5f6f8; --panel:#ffffff; --panel2:#f0f1f5; --text:#1c1e26; --muted:#6a6f80; --line:#e2e4ea; }
15	  }
16	  * { box-sizing: border-box; }
17	  body { margin: 0; font: 14px/1.5 ui-sans-serif, system-ui, sans-serif; background: var(--bg); color: var(--text); }
18	  header { display:flex; align-items:center; gap:12px; padding:16px 24px; border-bottom:1px solid var(--line); position:sticky; top:0; background:var(--bg); z-index:2; flex-wrap:wrap; }
19	  header h1 { font-size:16px; margin:0; font-weight:600; }
20	  body.task header h1 { cursor:pointer; }
21	  body.task header h1:hover { text-decoration:underline; text-underline-offset:3px; }
22	  #crumb { color:var(--muted); font-size:12px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:40vw; }
23	  #taskSel, #rateSel { background:var(--panel2); color:var(--text); border:1px solid var(--line); border-radius:6px; padding:3px 8px; font:12px/1.4 inherit; max-width:280px; }
24	  #rate { display:inline-flex; align-items:center; gap:6px; color:var(--muted); font-size:12px; }
25	  #conn { display:inline-flex; align-items:center; gap:6px; color:var(--muted); font-size:12px; }
26	  #conn .dot { width:8px; height:8px; border-radius:50%; background:var(--failed); }
27	  #conn.on .dot { background: var(--done); }
28	  #overall { margin-left:auto; color:var(--muted); font-size:12px; }
29	  body.home #taskSel, body.home #conn, body.home #rate, body.home #overall { display:none; }
30	  /* auto-fill (not auto-fit): with few plans on a wide screen, empty tracks
31	     keep each card at a readable ~380-520px instead of stretching it edge to edge */
32	  main#cards { padding: 20px 24px; display:grid; gap:16px; grid-template-columns:repeat(auto-fill, minmax(min(380px, 100%), 1fr)); max-width:1600px; margin:0 auto; align-items:start; }
33	  body.home main#cards { display:none; }
34	  main#home { padding: 24px; display:grid; gap:14px; grid-template-columns:repeat(auto-fill, minmax(min(280px, 100%), 1fr)); max-width:1200px; margin:0 auto; }
35	  body.task main#home { display:none; }
36	  .tile { background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:14px 16px; cursor:pointer; display:flex; flex-direction:column; gap:8px; transition:border-color .15s, transform .15s; }
37	  .tile:hover, .tile:focus-visible { border-color:var(--info); transform:translateY(-2px); }
38	  .tile:focus-visible { outline:2px solid var(--info); outline-offset:2px; }
39	  .tile h3 { margin:0; font-size:14px; font-weight:600; display:flex; align-items:center; gap:8px; overflow-wrap:anywhere; flex-wrap:wrap; }
40	  .tile .meta { color:var(--muted); font-size:12px; }
41	  .tile .lastline { color:var(--muted); font-size:12px; font-family:ui-monospace, monospace; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
42	  .card { background:var(--panel); border:1px solid var(--line); border-radius:10px; overflow:hidden; display:flex; flex-direction:column; }
43	  .card.wide { grid-column: 1 / -1; }
44	  .card h2 { font-size:13px; font-weight:600; margin:0; padding:12px 14px; display:flex; flex-wrap:wrap; align-items:center; gap:4px 10px; border-bottom:1px solid var(--line); min-width:0; }
45	  .card h2 .title { max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
46	  .badge { display:inline-flex; align-items:center; gap:5px; font-size:11px; font-weight:600; padding:2px 9px; border-radius:99px; text-transform:uppercase; letter-spacing:.04em; color:#0f1117; background:var(--queued); }
47	  .badge.running { background:var(--running); animation:runpulse 1.1s ease-in-out infinite; }
48	  .badge.running::before { content:""; width:7px; height:7px; border-radius:50%; border:2px solid #0f1117; border-top-color:transparent; animation:spin .7s linear infinite; }
49	  .badge.done { background:var(--done); }
50	  .badge.failed { background:var(--failed); }
51	  .badge.info { background:var(--info); }
52	  .tok { margin-left:auto; color:var(--muted); font-weight:500; font-size:11px; font-variant-numeric:tabular-nums; white-space:nowrap; max-width:100%; overflow:hidden; text-overflow:ellipsis; }
53	  .tok.bump { animation:tokbump .5s ease-out; }
54	  @keyframes tokbump { 0% { color:var(--running); transform:scale(1.12); } 100% { color:var(--muted); transform:scale(1); } }
55	  @keyframes spin { to { transform:rotate(360deg); } }
56	  @keyframes runpulse {
57	    0%, 100% { box-shadow:0 0 0 0 rgba(232,178,60,.6); transform:scale(1); }
58	    50%      { box-shadow:0 0 0 8px rgba(232,178,60,0); transform:scale(1.07); }
59	  }
60	  .flow { display:flex; gap:4px; align-items:center; padding:10px 14px; flex-wrap:wrap; border-bottom:1px solid var(--line); font-size:11px; }
61	  .flow:empty { display:none; }
62	  .flow .node { padding:2px 9px; border-radius:99px; border:1px solid var(--line); color:var(--muted); font-weight:600; }
63	  .flow .node.running { border-color:var(--running); color:var(--running); animation:chipblink 1.1s ease-in-out infinite; }
64	  .flow .node.done { border-color:var(--done); color:var(--done); }
65	  .flow .node.failed { border-color:var(--failed); color:var(--failed); }
66	  .flow .arrow { color:var(--muted); }
67	  .flow .loopback { color:var(--running); font-weight:600; margin-left:4px; }
68	  .agents { list-style:none; margin:0; padding:6px 0; border-bottom:1px solid var(--line); font-size:12px; }
69	  .agents:empty { display:none; }
70	  /* flex-wrap: the token counter is long and nowrap — when the row is tight it
71	     must wrap to its own line, never squeeze the agent name out of view */
72	  .agents li { display:flex; flex-wrap:wrap; gap:2px 10px; align-items:center; padding:2px 14px; font-family:ui-monospace, monospace; min-width:0; }
73	  .agents .dot { width:8px; height:8px; border-radius:50%; background:var(--queued); flex:none; }
74	  .agents li.running .dot { background:var(--running); animation:chipblink 1.1s ease-in-out infinite; }
75	  .agents li.done .dot { background:var(--done); }
76	  .agents li.failed .dot { background:var(--failed); }
77	  .agents li.stale { opacity:.55; }
78	  .log li.stale .s { color:var(--muted); }
79	  .agents .alabel { font-weight:600; max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
80	  .agents .atok { margin-left:auto; color:var(--muted); font-variant-numeric:tabular-nums; white-space:nowrap; max-width:100%; overflow:hidden; text-overflow:ellipsis; }
81	  .agents .adur { color:var(--muted); min-width:52px; text-align:right; font-variant-numeric:tabular-nums; }
82	  .stagebar { display:flex; gap:6px; padding:10px 14px; flex-wrap:wrap; border-bottom:1px solid var(--line); background:var(--panel2); }
83	  .chip { font-size:11px; padding:2px 8px; border-radius:6px; border:1px solid var(--line); color:var(--muted); }
84	  .chip.running { border-color:var(--running); color:var(--running); animation:chipblink 1.1s ease-in-out infinite; }
85	  @keyframes chipblink { 50% { opacity:.45; } }
86	  .chip.done { border-color:var(--done); color:var(--done); }
87	  .chip.failed { border-color:var(--failed); color:var(--failed); }
88	  .chip.stale { opacity:.55; }
89	  .log { list-style:none; margin:0; padding:8px 0; max-height:300px; overflow-y:auto; overscroll-behavior:contain; font-family:ui-monospace, monospace; font-size:12px; flex:1; scrollbar-width:thin; }
90	  .log li { padding:3px 14px; display:flex; gap:10px; border-left:3px solid transparent; }
91	  .log li .t { color:var(--muted); flex:none; }
92	  .log li .s { flex:none; width:64px; font-weight:600; }
93	  .log li.running { border-left-color:var(--running); } .log li.running .s { color:var(--running); }
94	  .log li.done { border-left-color:var(--done); } .log li.done .s { color:var(--done); }
95	  .log li.failed { border-left-color:var(--failed); } .log li.failed .s { color:var(--failed); }
96	  .log li.info .s { color:var(--info); }
97	  .log li .d { overflow-wrap:anywhere; }
98	  .empty { color:var(--muted); padding:14px; font-size:12px; grid-column:1/-1; }
99	  /* Artifacts row: final HTML report link + .md note previews (task view only).
100	     Lives inside the cards grid as a full-width row placed after the loop
101	     cards and before the wide orchestrator card. */
102	  #artifacts { display:none; grid-column:1 / -1; flex-wrap:wrap; gap:8px; align-items:center; }
103	  body.task #artifacts.has { display:flex; }
104	  #artifacts .ahdr { color:var(--muted); font-size:11px; font-weight:600; text-transform:uppercase; letter-spacing:.06em; }
105	  .artlink { font:12px/1.4 inherit; background:var(--panel); color:var(--text); border:1px solid var(--line); border-radius:99px; padding:3px 12px; cursor:pointer; text-decoration:none; display:inline-flex; align-items:center; gap:6px; max-width:340px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
106	  .artlink:hover, .artlink:focus-visible { border-color:var(--info); color:var(--info); }
107	  .artlink.report { border-color:var(--done); color:var(--done); font-weight:600; }
108	  .artlink.report:hover, .artlink.report:focus-visible { border-color:var(--done); filter:brightness(1.2); }
109	  /* Markdown preview modal */
110	  #mdOverlay { position:fixed; inset:0; background:rgba(0,0,0,.55); z-index:10; display:none; align-items:center; justify-content:center; padding:24px; }
111	  #mdOverlay.open { display:flex; }
112	  #mdBox { background:var(--panel); border:1px solid var(--line); border-radius:12px; width:min(900px, 100%); max-height:90vh; display:flex; flex-direction:column; overflow:hidden; }
113	  .mdhead { display:flex; align-items:center; gap:12px; padding:10px 16px; border-bottom:1px solid var(--line); }
114	  .mdhead .fname { font-weight:600; font-size:13px; font-family:ui-monospace, monospace; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
115	  .mdhead a { color:var(--info); font-size:12px; margin-left:auto; flex:none; }
116	  .mdhead button { background:none; border:none; color:var(--muted); font-size:16px; cursor:pointer; padding:2px 6px; flex:none; }
117	  .mdhead button:hover { color:var(--text); }
118	  #mdBody { padding:16px 20px; overflow:auto; overscroll-behavior:contain; font-size:13px; scrollbar-width:thin; }
119	  #mdBody h1, #mdBody h2, #mdBody h3, #mdBody h4 { margin:14px 0 6px; line-height:1.3; }
120	  #mdBody h1 { font-size:17px; } #mdBody h2 { font-size:15px; } #mdBody h3, #mdBody h4 { font-size:13px; }
121	  #mdBody p, #mdBody ul, #mdBody ol, #mdBody table, #mdBody blockquote { margin:6px 0; }
122	  #mdBody pre { background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:10px 12px; overflow-x:auto; font-size:12px; }
123	  #mdBody code { font-family:ui-monospace, monospace; background:var(--panel2); padding:1px 4px; border-radius:4px; font-size:12px; }
124	  #mdBody pre code { background:none; padding:0; }
125	  #mdBody blockquote { border-left:3px solid var(--line); padding:2px 12px; color:var(--muted); }
126	  #mdBody table { border-collapse:collapse; display:block; overflow-x:auto; max-width:100%; }
127	  #mdBody th, #mdBody td { border:1px solid var(--line); padding:4px 10px; text-align:left; }
128	  #mdBody th { background:var(--panel2); }
129	  #mdBody a { color:var(--info); }
130	  #mdBody hr { border:none; border-top:1px solid var(--line); margin:12px 0; }
131	  /* Wide screens: the full-width orchestrator card splits into two columns —
132	     flow/agents/stages on the left, the log filling the right — so a short
133	     log no longer sits alone in a huge empty strip. */
134	  @media (min-width: 1100px) {
135	    .card.wide { display:grid; grid-template-columns:minmax(340px, 34%) 1fr;
136	                 grid-template-rows:auto auto auto auto 1fr;
137	                 grid-template-areas:"h h" "flow log" "agents log" "stage log" ". log"; }
138	    .card.wide h2 { grid-area:h; }
139	    .card.wide .flow { grid-area:flow; }
140	    .card.wide .agents { grid-area:agents; }
141	    .card.wide .stagebar { grid-area:stage; }
142	    .card.wide .log { grid-area:log; border-left:1px solid var(--line); max-height:420px; }
143	    .log li .d { max-width:90ch; }
144	  }
145	  @media (max-width: 640px) {
146	    header { padding:10px 12px; gap:8px; }
147	    main#cards { padding:12px; gap:12px; }
148	    main#home { padding:12px; gap:10px; }
149	    #crumb { display:none; }
150	    #taskSel { max-width:48vw; }
151	    /* ≥16px stops iOS Safari from auto-zooming on focus; extra padding = tap target */
152	    #taskSel, #rateSel { font-size:16px; padding:6px 10px; }
153	    #overall { flex-basis:100%; margin-left:0; }
154	    #mdOverlay { padding:8px; }
155	    .artlink { max-width:100%; }
156	    .log { max-height:45vh; }
157	    .log li { flex-wrap:wrap; }
158	    .log li .s { width:auto; min-width:48px; }
159	    .agents .adur { min-width:44px; }
160	  }
161	  @media (prefers-reduced-motion: reduce) {
162	    *, *::before, *::after { animation:none !important; transition:none !important; }
163	  }
164	</style>
165	</head>
166	<body>
167	<header>
168	  <h1 id="pageTitle" title="all tasks">orchestrator monitor</h1>
169	  <span id="crumb"></span>
170	  <select id="taskSel" title="switch task"></select>
171	  <span id="conn"><span class="dot"></span><span id="connText">connecting…</span></span>
172	  <label id="rate">refresh <select id="rateSel" title="forced full-resync interval (live = websocket push only)">
173	    <option value="0">live</option>
174	    <option value="500">500ms</option>
175	    <option value="1000">1s</option>
176	    <option value="2000">2s</option>
177	    <option value="5000">5s</option>
178	    <option value="10000">10s</option>
179	    <option value="30000">30s</option>
180	    <option value="60000">1m</option>
181	  </select></label>
182	  <span id="overall"></span>
183	</header>
184	<main id="home"></main>
185	<main id="cards"><div id="artifacts"></div></main>
186	<div id="mdOverlay" role="dialog" aria-modal="true">
187	  <div id="mdBox">
188	    <div class="mdhead">
189	      <span class="fname" id="mdName"></span>
190	      <a id="mdRaw" target="_blank" rel="noopener">open raw</a>
191	      <button id="mdClose" title="close (Esc)">✕</button>
192	    </div>
193	    <article id="mdBody"></article>
194	  </div>
195	</div>
196	<script>
197	// Two URL-routed views, the query string is the single source of truth:
198	//   /              -> home: grid of every task folder, click-through to a task
199	//   /?task=<name>  -> that task's live progress page (survives refresh/share)
200	// Dropdown changes and tile clicks pushState; back/forward re-route.
201	const plans = new Map();
202	
203	function planEl(id) {
204	  if (plans.has(id)) return plans.get(id);
205	  const card = document.createElement("section");
206	  card.className = "card" + (id === "orchestrator" ? " wide" : "");
207	  card.innerHTML = `<h2><span class="badge">queued</span><span class="title"></span><span class="tok"></span></h2>
208	    <div class="flow"></div><ul class="agents"></ul><div class="stagebar"></div><ul class="log"></ul>`;
209	  card.querySelector(".title").textContent = id === "orchestrator" ? "Orchestrator" : id;
210	  const entry = { card, badge: card.querySelector(".badge"), stagebar: card.querySelector(".stagebar"),
211	                  log: card.querySelector(".log"), tok: card.querySelector(".tok"),
212	                  titleEl: card.querySelector(".title"),
213	                  flowEl: card.querySelector(".flow"), agentsEl: card.querySelector(".agents"),
214	                  agents: new Map(), roles: new Map(),
215	                  tokIn: 0, tokOut: 0, tokCached: 0, tokWrite: 0, stages: new Map(), state: "queued" };
216	  plans.set(id, entry);
217	  render();
218	  return entry;
219	}
220	function render() {
221	  const cards = document.getElementById("cards");
222	  for (const id of plans.keys())
223	    if (id !== "orchestrator") cards.appendChild(plans.get(id).card);
224	  if (plans.has("orchestrator")) cards.appendChild(plans.get("orchestrator").card);
225	  placeArtifacts();  // artifacts row sits after the loop cards, before the orchestrator card
226	  let done = 0, failed = 0, running = 0;
227	  for (const [id, p] of plans) {
228	    if (id === "orchestrator") continue;
229	    if (p.state === "done") done++; else if (p.state === "failed") failed++; else if (p.state === "running") running++;
230	  }
231	  let tin = 0, tout = 0, tcached = 0, twrite = 0;
232	  for (const p of plans.values()) { tin += p.tokIn; tout += p.tokOut; tcached += p.tokCached; twrite += p.tokWrite; }
233	  if (plans.has("orchestrator") && tin + tout)
234	    setTok(plans.get("orchestrator").tok, `Σ ${fmtIn(tin, tcached, twrite)} · out ${fmtTok(tout)}`);
235	  document.getElementById("overall").textContent =
236	    `${done} done · ${running} running · ${failed} failed · ${plans.size - (plans.has("orchestrator")?1:0)} plans` +
237	    (tin + tout ? ` · ${fmtIn(tin, tcached, twrite)} · out ${fmtTok(tout)}` : "");
238	}
239	function fmtTok(n) {
240	  if (n >= 1e6) return (n / 1e6).toFixed(2) + "M";
241	  return n >= 1000 ? (n / 1000).toFixed(1) + "k" : String(n);
242	}
243	// Input-side display: "in 3k - r:1k w:2k" (r = cache read, w = cache write).
244	// An agent loop re-reads its whole conversation prefix every turn, so cache
245	// reads dominate "in" (and cost ~10x less than fresh input). The r:/w: parts
246	// appear only when the event stream carries the breakdown; events from
247	// pre-split watchers lack them and keep the plain "in 3k" form.
248	function fmtIn(tin, cached, write) {
249	  const parts = [];
250	  if (cached > 0) parts.push(`r:${fmtTok(cached)}`);
251	  if (write > 0) parts.push(`w:${fmtTok(write)}`);
252	  return `in ${fmtTok(tin)}` + (parts.length ? " - " + parts.join(" ") : "");
253	}
254	let replaying = false, replayTimer = null;
255	function noteReplay() {  // history replay after (re)connect: suppress pulses until the burst ends
256	  if (!replaying) return;
257	  clearTimeout(replayTimer);
258	  replayTimer = setTimeout(() => { replaying = false; }, 600);
259	}
260	function setTok(el, text) {  // pulse only the counter whose value changed, and only live
261	  if (el.textContent === text) return;
262	  el.textContent = text;
263	  if (replaying) return;
264	  el.classList.remove("bump"); void el.offsetWidth; el.classList.add("bump");
265	}
266	// Per-subagent rows + loop-flow strip: watcher events carry an "agent" field
267	// ({id, label: "role #attempt", state, tokens, started, runtime}). Rows are
268	// keyed by agent id; the flow strip groups rows by role in first-seen order
269	// (that order IS the loop topology: impl -> gate -> e2e -> critique), each
270	// node showing the role's latest attempt + state, with a loop-back marker
271	// once any role passes attempt 1.
272	function upsertAgent(p, a, ts) {
273	  let row = p.agents.get(a.id);
274	  if (!row) {
275	    const li = document.createElement("li");
276	    li.innerHTML = `<span class="dot"></span><span class="alabel"></span><span class="atok"></span><span class="adur"></span>`;
277	    li.querySelector(".alabel").textContent = a.label || a.id;
278	    p.agentsEl.appendChild(li);
279	    row = { li, started: a.started || ts, state: "running",
280	            tok: li.querySelector(".atok"), dur: li.querySelector(".adur") };
281	    p.agents.set(a.id, row);
282	  }
283	  if (a.started) row.started = a.started;
284	  if (a.state) { row.state = a.state; row.li.className = a.state; }
285	  if (a.tokens) setTok(row.tok, `⟳ ${fmtIn(a.tokens.in || 0, a.tokens.cached || 0, a.tokens.cache_write || 0)} · out ${fmtTok(a.tokens.out || 0)}`);
286	  if (a.runtime) row.dur.textContent = a.runtime;
287	  const role = (a.label || a.id).split(" #")[0];
288	  const attempt = parseInt((a.label || "").split(" #")[1]) || 1;
289	  const node = p.roles.get(role) || { state: "running", attempt: 1 };
290	  if (a.state) node.state = a.state;
291	  node.attempt = Math.max(node.attempt, attempt);
292	  p.roles.set(role, node);
293	  renderFlow(p);
294	}
295	// events.jsonl is a multi-writer plain file, so agent.state is untrusted input.
296	// Build nodes with createElement + a whitelisted className and textContent (never
297	// interpolate n.state into an innerHTML string) so a hostile state value cannot
298	// break out of the class attribute and inject markup (FRONTEND-1).
299	const NODE_STATES = ["running", "done", "failed", "stale"];
300	function renderFlow(p) {
301	  p.flowEl.textContent = "";
302	  let maxAttempt = 1, first = true;
303	  for (const [role, n] of p.roles) {
304	    if (!first) {
305	      const arrow = document.createElement("span");
306	      arrow.className = "arrow"; arrow.textContent = "→";
307	      p.flowEl.appendChild(arrow);
308	    }
309	    first = false;
310	    const node = document.createElement("span");
311	    node.className = "node" + (NODE_STATES.includes(n.state) ? " " + n.state : "");
312	    node.textContent = role + (n.attempt > 1 ? " #" + n.attempt : "");
313	    p.flowEl.appendChild(node);
314	    maxAttempt = Math.max(maxAttempt, n.attempt);
